-- Unpushed correction: internal UUID IDs remain CHAR(36); provider identity is scoped separately.
ALTER TABLE products ADD COLUMN platform VARCHAR(24) NULL AFTER source, DROP INDEX products_external_scope, ADD UNIQUE KEY products_platform_external_scope (organization_id, store_id, platform, external_id);
ALTER TABLE variants ADD COLUMN platform VARCHAR(24) NULL AFTER source, DROP INDEX variants_external_scope, ADD UNIQUE KEY variants_platform_external_scope (organization_id, store_id, platform, external_id);
ALTER TABLE commerce_orders ADD COLUMN platform VARCHAR(24) NULL AFTER source, DROP INDEX orders_external_scope, ADD UNIQUE KEY orders_platform_external_scope (organization_id, store_id, platform, external_id);
ALTER TABLE order_items ADD COLUMN platform VARCHAR(24) NULL AFTER source, ADD UNIQUE KEY order_items_platform_external_scope (organization_id, store_id, platform, external_id);
CREATE TABLE customers (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, store_id CHAR(36) NOT NULL, platform VARCHAR(24) NOT NULL, external_id VARCHAR(191) NOT NULL, source VARCHAR(24) NOT NULL, display_name VARCHAR(255) NULL, email VARCHAR(320) NULL, phone VARCHAR(64) NULL, status VARCHAR(24) NOT NULL, source_updated_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY customers_platform_external_scope (organization_id, store_id, platform, external_id), KEY customers_scope (organization_id, store_id));
CREATE TABLE inventory_facts (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, store_id CHAR(36) NOT NULL, platform VARCHAR(24) NOT NULL, external_id VARCHAR(191) NOT NULL, product_id CHAR(36) NOT NULL, variant_id CHAR(36) NULL, current_stock INT NULL, available_stock INT NULL, reserved_stock INT NULL, inbound_stock INT NULL, source VARCHAR(24) NOT NULL, status VARCHAR(24) NOT NULL, observed_at TIMESTAMP NOT NULL, source_updated_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY inventory_platform_external_scope (organization_id, store_id, platform, external_id), KEY inventory_scope (organization_id, store_id, product_id));
